IOPS最小值:&#123;iopsMin&#125;,&quot;        f&quot;最大值&#123;iopsMax&#125;,均值&#123;iopsAvg&#125;&quot;    )# 创建读文件def create_readFile():    print(&quot;初始化读测试环境,至少需要十几分钟甚至几十分钟,等着...&quot;)    clear = subprocess.Popen([&quot;rm&quot;, &quot;-rf&quot;, &quot;/iopsTest/*&quot;], shell=False)    clear.wait()    print(&quot;环境检测完成,创建读测试文件...&quot;)    cmd = [        &quot;fio&quot;,        &quot;-name=create_read&quot;,        &quot;-size=32G&quot;,        &quot;-bs=1M&quot;,        &quot;-direct=1&quot;,        &quot;-rw=write&quot;,        &quot;-ioengine=libaio&quot;,        &quot;-numjobs=8&quot;,        &quot;-filename=/iopsTest/read&quot;,    ]    create = subprocess.Popen(cmd, stdout=subprocess.PIPE, shell=False)    done = create.communicate()[0].decode(&quot;utf-8&quot;)# 随机读def randread():    # 初始化用于存储运行结果的列表    bw = [0, 0, 0]    iops = [0, 0, 0]    # fio重复运行4次    print(&quot;随机读进行中...&quot;)    for i in range(4):        cmd = [            &quot;fio&quot;,            &quot;-name=YEOS&quot;,            &quot;-size=32G&quot;,            &quot;-runtime=60s&quot;,            &quot;-time_base&quot;,            &quot;-bs=4k&quot;,            &quot;-direct=1&quot;,            &quot;-rw=randwrite&quot;,            &quot;-ioengine=libaio&quot;,            &quot;-numjobs=8&quot;,            &quot;-group_reporting&quot;,            &quot;-iodepth=64&quot;,            &quot;-filename=/iopsTest/read&quot;,            &quot;-randrepeat=0&quot;,        ]        # 将fio运行结果标准输出到管道        fio1 = subprocess.Popen(cmd, stdout=subprocess.PIPE, shell=False)        fio2 = subprocess.Popen(            [&quot;grep&quot;, &quot;samples&quot;], stdin=fio1.stdout, stdout=subprocess.PIPE, shell=False        )        # 使用communicate获取子进程的标准输出并格式化为utf-8编码        fio = fio2.communicate()[0].decode(&quot;utf-8&quot;)        # 初始化列表        bw_num = []        iops_num = []        # 匹配数字和小数点，并将其元素更新        for line in fio.split(&quot;
