&quot;):                # 判断格式化的结果中是否存在MiB单位的值                if &quot;MiB&quot; in KorM:                    # 若有则转换为KiB                    print(&quot;输出结果为MiB单位,将进行转换&quot;)                    bw[0] += bw_num[0] * 1024                    bw[1] += bw_num[1] * 1024                    bw[2] += bw_num[3] * 1024                    iops[0] += iops_num[0]                    iops[1] += iops_num[1]                    iops[2] += iops_num[2]                    print(f&quot;带宽第&#123;i&#125;次值:&#123;bw&#125;&quot;)                    print(f&quot;IOPS第&#123;i&#125;次值:&#123;iops&#125;&quot;)                elif &quot;KiB&quot; in KorM:                    print(&quot;输出结果为KiB单位,不转换&quot;)                    bw[0] += bw_num[0]                    bw[1] += bw_num[1]                    bw[2] += bw_num[3]                    iops[0] += iops_num[0]                    iops[1] += iops_num[1]                    iops[2] += iops_num[2]                    print(f&quot;带宽第&#123;i&#125;次值:&#123;bw&#125;&quot;)                    print(f&quot;IOPS第&#123;i&#125;次值:&#123;iops&#125;&quot;)    bwMin = int(bw[0] / 3)    bwMax = int(bw[1] / 3)    bwAvg = int(bw[2] / 3)    iopsMin = int(iops[0] / 3)    iopsMax = int(iops[1] / 3)    iopsAvg = int(iops[2] / 3)    print(        f&quot;


