IOPS最小值:&#123;iopsMin&#125;,&quot;        f&quot;最大值&#123;iopsMax&#125;,均值&#123;iopsAvg&#125;&quot;    )# 随机读写def randrw():    # 初始化用于存储运行结果的列表    bw = [0, 0, 0, 0, 0, 0]    iops = [0, 0, 0, 0, 0, 0]    # fio重复运行4次    print(&quot;随机读写进行中...&quot;)    for i in range(4):        cmd = [            &quot;fio&quot;,            &quot;-name=YEOS&quot;,            &quot;-size=32G&quot;,            &quot;-runtime=60s&quot;,            &quot;-time_base&quot;,            &quot;-bs=4k&quot;,            &quot;-direct=1&quot;,            &quot;-rw=randrw&quot;,            &quot;-ioengine=libaio&quot;,            &quot;-numjobs=8&quot;,            &quot;-group_reporting&quot;,            &quot;-iodepth=64&quot;,            &quot;-filename=/iopsTest/read&quot;,            &quot;-rwmixwrite=30&quot;,            &quot;-randrepeat=0&quot;,        ]        # 将fio运行结果标准输出到管道        fio1 = subprocess.Popen(cmd, stdout=subprocess.PIPE, shell=False)        fio2 = subprocess.Popen(            [&quot;grep&quot;, &quot;samples&quot;], stdin=fio1.stdout, stdout=subprocess.PIPE, shell=False        )        # 使用communicate获取子进程的标准输出并格式化为utf-8编码        fio = fio2.communicate()[0].decode(&quot;utf-8&quot;)        # 初始化列表        bw_num = []        iops_num = []        # 匹配数字和小数点，并将其元素更新        for line in fio.split(&quot;
&quot;):            if &quot;bw&quot; in line:                bw_num.extend(re.findall(r&quot;\d+\.\d+|\d+&quot;, line))            elif &quot;iops&quot; in line:                iops_num.extend(re.findall(r&quot;\d+\.\d+|\d+&quot;, line))        # 将str类型转换为float后再转换为int        bw_num = [int(float(e)) for e in bw_num]        iops_num = [int(float(e)) for e in iops_num]        print(f&quot;单次带宽运行结果:&#123;bw_num&#125;&quot;)        print(f&quot;单次IOPS运行结果:&#123;iops_num&#125;&quot;)        # 跳过第一次运行结果        if i == 0:            continue        else:            # 格式化fio结果            for KorM in fio.split(&quot;
&quot;):                # 判断格式化的结果中是否存在MiB单位的值                if &quot;MiB&quot; in KorM:                    print(&quot;输出结果为MiB单位,将进行转换&quot;)                    # 若有则转换为KiB                    # 读带宽                    bw[0] += bw_num[0] * 1024                    bw[1] += bw_num[1] * 1024                    bw[2] += bw_num[3] * 1024                    # 写带宽                    bw[3] += bw_num[6] * 1024                    bw[4] += bw_num[7] * 1024                    bw[5] += bw_num[9] * 1024                    # 读IOPS                    iops[0] += iops_num[0]                    iops[1] += iops_num[1]                    iops[2] += iops_num[2]                    # 写IOPS                    iops[3] += iops_num[5]                    iops[4] += iops_num[6]                    iops[5] += iops_num[7]                    print(f&quot;带宽第&#123;i&#125;次值:&#123;bw&#125;&quot;)                    print(f&quot;IOPS第&#123;i&#125;次值:&#123;iops&#125;&quot;)                    # 因fio结果存在读写两行，避免重复执行，所以直接跳过后续循环                    break                elif &quot;KiB&quot; in KorM:                    print(&quot;输出结果为KiB单位,不转换&quot;)                    # 读带宽                    bw[0] += bw_num[0]                    bw[1] += bw_num[1]                    bw[2] += bw_num[3]                    # 写带宽                    bw[3] += bw_num[6]                    bw[4] += bw_num[7]                    bw[5] += bw_num[9]                    # 读IOPS                    iops[0] += iops_num[0]                    iops[1] += iops_num[1]                    iops[2] += iops_num[2]                    # 写IOPS                    iops[3] += iops_num[5]                    iops[4] += iops_num[6]                    iops[5] += iops_num[7]                    print(f&quot;带宽第&#123;i&#125;次值:&#123;bw&#125;&quot;)                    print(f&quot;IOPS第&#123;i&#125;次值:&#123;iops&#125;&quot;)                    # 因fio结果存在读写两行，避免重复执行，所以直接跳过后续循环                    break    RbwMin = int(bw[0] / 3)    RbwMax = int(bw[1] / 3)    RbwAvg = int(bw[2] / 3)    WbwMin = int(bw[3] / 3)    WbwMax = int(bw[4] / 3)    WbwAvg = int(bw[5] / 3)    RiopsMin = int(iops[3] / 3)    RiopsMax = int(iops[4] / 3)    RiopsAvg = int(iops[5] / 3)    WiopsMin = int(iops[0] / 3)    WiopsMax = int(iops[1] / 3)    WiopsAvg = int(iops[2] / 3)    print(        f&quot;


